import itertools

n = 14
# Build cycle edges
cycle_edges = set()
for i in range(n):
    cycle_edges.add((min(i, (i+1)%n), max(i, (i+1)%n)))

# All possible valid chords (no cycle < 7 by itself)
valid_chords = []
for i in range(n):
    for k in [6, 7, 8]:
        j = (i + k) % n
        if i < j:
            valid_chords.append((i, j))

print(f"Valid chords: {len(valid_chords)}")
print(valid_chords)

def edges_to_adj(edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    return adj

def girth(adj):
    # Returns length of shortest cycle, or float('inf') if acyclic
    shortest = float('inf')
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = [start]
        for u in queue:
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v and parent[v] != u:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < shortest:
                        shortest = cycle_len
    return shortest

def is_colorable(adj, max_colors=4):
    n = len(adj)
    colors = [-1] * n

    def dfs(u):
        for v in adj[u]:
            if colors[v] == -1:
                for c in range(max_colors):
                    ok = True
                    for w in adj[v]:
                        if colors[w] == c:
                            ok = False
                            break
                    if ok:
                        colors[v] = c
                        if dfs(v):
                            return True
                        colors[v] = -1
                return False
            elif colors[v] == colors[u]:
                return False
        return True

    for start in range(n):
        if colors[start] == -1:
            colors[start] = 0
            if not dfs(start):
                return False
    return True

base_edges = list(cycle_edges)
print(f"Base edges: {len(base_edges)}")

best_girth = 0
best_edges = None

for num_chords in range(5, 8):  # need at least 5 extra edges
    print(f"Trying {num_chords} chords...")
    count = 0
    for chords in itertools.combinations(valid_chords, num_chords):
        edges = base_edges + list(chords)
        adj = edges_to_adj(edges)
        g = girth(adj)
        if g >= 7:
            if is_colorable(adj, 4):
                print(f"Found! Edges: {edges}, girth: {g}, edges: {len(edges)}")
                best_edges = edges
                best_girth = g
                break
        count += 1
    if best_edges:
        break
    print(f"Checked {count} combinations")

if best_edges:
    print("Success!")
    print(f"Edges ({len(best_edges)}): {sorted(best_edges)}")
else:
    print("No luck with C_14 + chords")

import itertools
import random

# Try bipartite graph with parts A={0..6}, B={7..13}
# Represent as 7x7 binary matrix

def has_4cycle(matrix):
    # Check for any 2x2 submatrix of all 1s
    for i1 in range(7):
        for i2 in range(i1+1, 7):
            for j1 in range(7):
                for j2 in range(j1+1, 7):
                    if matrix[i1][j1] and matrix[i1][j2] and matrix[i2][j1] and matrix[i2][j2]:
                        return True
    return False

def has_6cycle(matrix):
    # Build adjacency and check for 6-cycles
    n = 14
    adj = [[] for _ in range(n)]
    for i in range(7):
        for j in range(7):
            if matrix[i][j]:
                u = i
                v = 7 + j
                adj[u].append(v)
                adj[v].append(u)

    # BFS from each vertex to find shortest cycle
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = [start]
        for u in queue:
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v:
                    # cycle found
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= 6:
                        return True
    return False

def count_edges(matrix):
    return sum(sum(row) for row in matrix)

# Try random search
random.seed(42)
best = 0
best_matrix = None

for trial in range(100000):
    matrix = [[0]*7 for _ in range(7)]
    # Start with a random set of edges
    edges = []
    for i in range(7):
        for j in range(7):
            if random.random() < 0.4:
                matrix[i][j] = 1

    if has_4cycle(matrix) or has_6cycle(matrix):
        continue

    e = count_edges(matrix)
    if e >= 19:
        print(f"Found with {e} edges!")
        best_matrix = matrix
        break
    elif e > best:
        best = e

print(f"Best random: {best}")

# Try greedy construction
if best_matrix is None:
    matrix = [[0]*7 for _ in range(7)]
    positions = [(i,j) for i in range(7) for j in range(7)]
    random.shuffle(positions)

    for i, j in positions:
        matrix[i][j] = 1
        if has_4cycle(matrix) or has_6cycle(matrix):
            matrix[i][j] = 0

    e = count_edges(matrix)
    print(f"Greedy edges: {e}")
